import React from 'react';
import { FaUserCircle, FaCheckCircle } from 'react-icons/fa';
import { HiChevronRight } from 'react-icons/hi';

export default function Landlord() {
  const landlords = [
    {
      name: 'Rizal Boardinghouse',
      address: 'Gen. Luna, La Paz Iloilo City',
    },
    {
      name: 'Shiena Boardinghouse',
      address: 'Barangay Bakhaw, Mandurriao Iloilo City',
    },
    {
      name: 'Tanya Boardinghouse',
      address: 'Brgy Tacas, Jaro, Iloilo City',
    },
    {
      name: 'Sarrah Boardinghouse',
      address: 'Iloilo City',
    },
  ];

  return (
    <div className="bg-white min-h-screen text-gray-800">
      {/* Navbar */}
      <nav className="bg-blue-500 text-white flex items-center justify-between px-8 py-4 shadow-md">
        <div className="flex items-center space-x-3">
          <img src="/logo.png" alt="Logo" className="h-8 w-8" />
          <span className="font-bold text-lg">RENTER GO</span>
        </div>
        <div className="space-x-6">
          <a href="/" className="hover:text-gray-200">Home</a>
          <a href="/landlord" className="font-semibold border-b-2 border-white">Landlord</a>
          <a href="/about" className="hover:text-gray-200">About</a>
          <a href="/contact" className="hover:text-gray-200">Contact Us</a>
        </div>
        <div>
          <button className="text-white text-xl">
            <FaUserCircle />
          </button>
        </div>
      </nav>

      {/* Main Content */}
      <div className="max-w-2xl mx-auto mt-10 px-4">
        <h2 className="text-2xl font-bold mb-6">See Landlords Info</h2>

        <div className="space-y-4">
          {landlords.map((landlord, index) => (
            <div
              key={index}
              className="flex justify-between items-center border rounded-xl p-4 shadow-sm hover:shadow-md transition"
            >
              <div className="flex items-center space-x-3">
                <img
                  src="/avatar.png"
                  alt="Avatar"
                  className="h-10 w-10 rounded-full"
                />
                <div>
                  <h3 className="font-semibold flex items-center gap-1">
                    {landlord.name}
                    <FaCheckCircle className="text-blue-500 text-sm" />
                  </h3>
                  <p className="text-gray-600 text-sm">{landlord.address}</p>
                </div>
              </div>
              <HiChevronRight className="text-gray-600 text-xl" />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
